'use strict';
// One world, one resolver: combat is a map state with a card tray, not another scene.
const mapCamera={zoom:1,target:1,min:.75,max:5,pointers:new Map(),pinchDistance:0,lastPinch:-Infinity};
function setMapZoom(value){mapCamera.target=Math.max(mapCamera.min,Math.min(mapCamera.max,value));$('zoomValue').textContent=Math.round(mapCamera.target*100)+'%'}
function sampleMapZoom(dt){const factor=preferences.reduceMotion||reducedMotion?.matches?1:1-Math.exp(-dt/100);mapCamera.zoom+=(mapCamera.target-mapCamera.zoom)*factor;return mapCamera.zoom}
function mapCameraTarget(){return combat?.onMap?{x:(state.x+combat.mapEnemy.x)/2,y:(state.y+combat.mapEnemy.y)/2}:{x:motion.x,y:motion.y}}
function mapCameraLift(h){if(!combat?.onMap)return 0;const header=$('mapBattleStatus').getBoundingClientRect().height||120;return Math.max(0,((combat.panelReserve||280)-header)/2)}
function fitMapEncounter(){if(!combat?.onMap)return;const w=canvas.getBoundingClientRect().width,h=canvas.getBoundingClientRect().height;const dx=Math.abs(state.x-combat.mapEnemy.x),dy=Math.abs(state.y-combat.mapEnemy.y);setMapZoom(Math.min(3.5,w/(Math.max(4,dx+3)*CFG.tile),(h*.52)/(Math.max(5,dy+3)*CFG.tile)))}
const saveWorldBeforeMapCombat=save;save=function(){if(combat?.onMap&&combat.practice)return;saveWorldBeforeMapCombat()};
function prepareMapEncounter(c){if(c.onMap)return;c.onMap=true;c.zoomBefore=mapCamera.target;c.snapshot=c.practice?JSON.stringify({...state,seen:[...state.seen]}):null;
 const source=enemies.find(e=>e.id===c.place.entityId)||enemies.find(e=>e.type===(c.place.enemyType||'guardian')&&enemyAlive(e))||(c.practice?enemies.find(e=>e.type==='boar'):null);
 c.sourceId=source?.id;c.mapEnemy=source?{...source,type:c.place.enemyType||source.type}:{id:'map-encounter',type:c.place.enemyType||'guardian',name:c.enemy.name,x:Math.min(CFG.size-2,state.x+2),y:state.y};
 if(c.practice){state.clock=.42;const offsets=[[-2,1],[-2,0],[0,2],[2,0],[0,-2],[-1,0],[1,0],[0,1]];const spot=offsets.map(([dx,dy])=>({x:c.mapEnemy.x+dx,y:c.mapEnemy.y+dy})).find(p=>p.x>0&&p.y>0&&p.x<CFG.size-1&&p.y<CFG.size-1&&!['water','tree','mountain'].includes(tiles[idx(p.x,p.y)].type));if(spot){state.x=spot.x;state.y=spot.y}c.player.hp=c.player.maxHP;c.player.mana=maxMana()}
 c.mapEnemy.name=c.enemy.name;stageMapCombat(c);closeGuidedSurface();if($('modal').open)$('modal').close();$('modalContent').innerHTML='';atlas=false;$('atlasInfo').hidden=true;keys.clear();clickTarget=null;dismissSpeech();setLifeMode('play');document.body.classList.add('map-in-combat');document.body.classList.remove('map-has-result');resetMotion();reveal();updateUI();fitMapEncounter();
}
const previousCombatSurface=showCombatSurface;showCombatSurface=function(html,guided=false){if(!combat?.onMap){previousCombatSurface(html,guided);return}const start=html.indexOf('<div class="combat-command">');$('mapBattlePanel').innerHTML=start>=0?html.slice(start):html;$('mapBattlePanel').hidden=false;$('modalContent').innerHTML='<button class="close" hidden></button>';$('mapBattlePanel').setAttribute('aria-busy','false')};
const previousCombatRender=renderCombat;renderCombat=function(){if(!combat)return;prepareMapEncounter(combat);const oldScroll=$('mapBattlePanel').querySelector('.battle-cards')?.scrollLeft||0;previousCombatRender();if(!combat.panelReserve)combat.panelReserve=$('mapBattlePanel').getBoundingClientRect().height||280;const tray=$('mapBattlePanel').querySelector('.battle-cards');if(tray)tray.scrollLeft=oldScroll;const c=combat;$('mapBattleStatus').hidden=false;$('mapBattleStatus').innerHTML=`<span class="eyebrow">${c.practice?'PRACTICE':'ENCOUNTER'} · ROUND ${c.round}</span><span>${c.phase==='reveal'?'Both hands revealed':'Choose your hand'}</span><small>${c.player.mana} mana · ✦ ${c.player.dice} dice</small>`;renderMapUnitLabels(c);if(!c.practice&&c.phase!=='reveal')$('surrenderBattle').onclick=()=>finishMapEncounter('defeat')};
const previousAnimateCombat=animateCombatRound;animateCombatRound=function(c){if(!c.onMap){previousAnimateCombat(c);return}c.effectStarted=performance.now();if(preferences.reduceMotion||reducedMotion?.matches)return;const panel=$('mapBattlePanel'),button=$('commitHand'),label=button.textContent;button.disabled=true;button.textContent='Resolving both hands…';panel.classList.add('battle-playing');setTimeout(()=>{if(combat!==c)return;panel.classList.remove('battle-playing');$('commitHand').disabled=false;$('commitHand').textContent=label},MAP_FX.duration)};
const previousNextRound=nextBattleRound;nextBattleRound=function(){if(!combat?.onMap){previousNextRound();return}if(combat.result?.outcome){finishMapEncounter(combat.result.outcome);return}combat.round++;combat.phase='choose';combat.hand=[];combat.actionFailure='';combat.enemyHand=battleChoose(combat.enemy,random);renderCombat()};
const previousAlternative=battleAlternative;battleAlternative=function(kind){if(!combat?.onMap){previousAlternative(kind);return}const c=combat,p=state.character.pillars;let chance;if(kind==='flee'){if(c.fleeAttempts>=BATTLE.fleeAttempts)return;c.fleeAttempts++;chance=Math.min(.85,BATTLE.fleeBase+p.instinct*BATTLE.fleePerInstinct)}else{if(c.negotiated)return;c.negotiated=true;chance=Math.min(.75,BATTLE.negotiateBase+(p.influence+p.wit)*BATTLE.negotiatePerPillar)}if(random()<chance){finishMapEncounter(kind==='flee'?'escaped':'negotiated');return}c.actionFailure=kind==='flee'?'Escape failed. ':'Negotiation refused. ';c.hand=[];commitBattleHand()};
function restoreMapPractice(c){if(!c?.snapshot)return;state=JSON.parse(c.snapshot);state.seen=new Set(state.seen);hydrateLife();resetMotion();updateUI()}
function finishMapEncounter(outcome){const c=combat;if(!c?.onMap)return;const practice=c.practice,won=['victory','negotiated'].includes(outcome);let title,detail;
 if(practice){restoreMapPractice(c);title=won?'Practice complete · the path is clear.':outcome==='escaped'?'Practice complete · you escaped.':'Practice complete · return to the hearth.';detail='Your saved health, items and progress are unchanged.'}
 else if(won){const p=c.place;if(p.entityId&&!state.defeatedEnemies.includes(p.entityId))state.defeatedEnemies.push(p.entityId);if(p.encounter){state.gold+=12;state.xp+=CFG.combatXP;title='The path is clear.';detail=`+12 gold · +${CFG.combatXP} XP. This opponent stays cleared on your map.`}else{if(!state.relics.includes(p.id))state.relics.push(p.id);if(!state.cleared.includes(p.id))state.cleared.push(p.id);state.gold+=20;state.xp+=CFG.relicXP;state.mana=Math.min(maxMana(),state.mana+5);title=p.relic+' recovered.';detail=`+20 gold · +${CFG.relicXP} XP. The guardian is cleared.`}}
 else if(outcome==='escaped'){title='You reach the safe village.';detail='The opponent remains where you left it.'}
 else{const protectedByVault=state.vaults>0;if(protectedByVault)state.vaults--;else state.xp=Math.max(0,state.xp-20);title=protectedByVault?'Your Vault brings you home.':'You return to Hearthstead.';detail=protectedByVault?'One Vault Card consumed. Your progress is protected.':'You reincarnate at your village, losing up to 20 XP.'}
 combat=null;keys.clear();clickTarget=null;document.body.classList.remove('map-in-combat');document.body.classList.add('map-has-result');$('mapBattleStatus').hidden=true;hideMapUnitLabels();setMapZoom(c.zoomBefore||1);if(!practice&&!won){goHome(outcome!=='escaped')}else{resetMotion();updateUI()}save();$('mapBattlePanel').hidden=false;$('mapBattlePanel').innerHTML=`<div class="map-result"><span class="eyebrow">${practice?'PRACTICE FINISHED':'BACK TO YOUR JOURNEY'}</span><strong>${escapeText(title)}</strong><p>${escapeText(detail)}</p><div><button class="quiet" id="continueOnMap">Continue exploring</button>${practice?'<button class="quiet" id="repeatMapPractice">Try another hand</button>':''}</div></div>`;$('continueOnMap').onclick=()=>{$('mapBattlePanel').hidden=true;document.body.classList.remove('map-has-result');canvas.focus()};if(practice)$('repeatMapPractice').onclick=()=>startCombat({...c.place,practice:true});canvas.focus();
}
const previousVictory=victory;victory=function(message){if(combat?.onMap)finishMapEncounter('victory');else previousVictory(message)};
const previousFinishTurn=finishTurn;finishTurn=function(){if(combat?.onMap&&state.hp<=0){finishMapEncounter('defeat');return}if(combat?.onMap){renderCombat();return}previousFinishTurn()};
const previousPracticeResult=showPracticeResult;showPracticeResult=function(outcome){if(combat?.onMap)finishMapEncounter(outcome);else previousPracticeResult(outcome)};
const previousLeavePractice=leavePractice;leavePractice=function(){if(combat?.onMap){const c=combat;restoreMapPractice(c);combat=null;setMapZoom(c.zoomBefore||1);$('mapBattlePanel').hidden=true;$('mapBattleStatus').hidden=true;hideMapUnitLabels();document.body.classList.remove('map-in-combat','map-has-result');save();setLifeMode('play');return}previousLeavePractice()};
showEncounterWalkthrough=function(){startCombat({name:'Forest edge',enemyType:'boar',practice:true,guided:true,encounter:true})};
combatPracticeMenu=function(){setLifeMode('practice');$('opening').innerHTML=`<div class="flow-panel narrow"><button class="back-link" id="practiceMenuBack">← Main menu</button><div class="eyebrow">PRACTICE ON YOUR MAP</div><h1>Choose an opponent.</h1><p>The camera frames a real location in your world. Practice never changes your saved journey.</p><button class="primary" id="guidedMapPractice">Guided boar encounter →</button><div class="practice-opponents">${Object.entries(BATTLE.enemies).map(([type,e])=>`<button class="quiet" data-map-practice="${type}">${e.name}</button>`).join('')}</div></div>`;$('practiceMenuBack').onclick=mainMenu;$('guidedMapPractice').onclick=showEncounterWalkthrough;document.querySelectorAll('[data-map-practice]').forEach(b=>b.onclick=()=>startCombat({name:'Map practice',enemyType:b.dataset.mapPractice,practice:true,encounter:true}))};
const previousDrawEnemies=drawEnemies;drawEnemies=function(ox,oy,t){if(!combat?.onMap){previousDrawEnemies(ox,oy,t);return}if(atlas)return;for(const e of enemies)if(enemyAlive(e)&&state.seen.has(idx(e.x,e.y))&&(!combat.practice||e.id!==combat.sourceId))drawEnemy(e,ox+(e.x+.5)*t,oy+(e.y+.5)*t,t);if(combat.practice)drawEnemy(combat.mapEnemy,ox+(combat.mapEnemy.x+.5)*t,oy+(combat.mapEnemy.y+.5)*t,t)};
$('zoomIn').onclick=()=>setMapZoom(mapCamera.target+.25);$('zoomOut').onclick=()=>setMapZoom(mapCamera.target-.25);$('zoomReset').onclick=()=>combat?.onMap?fitMapEncounter():setMapZoom(1);setMapZoom(1);
canvas.addEventListener('wheel',e=>{if(lifeMode!=='play'||atlas)return;e.preventDefault();setMapZoom(mapCamera.target*(e.deltaY<0?1.12:.89))},{passive:false});
document.addEventListener('keydown',e=>{if(lifeMode!=='play'||['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if(['+','=','-','0'].includes(e.key)){e.preventDefault();if(e.key==='0')$('zoomReset').onclick();else setMapZoom(mapCamera.target+(e.key==='-'?-.25:.25))}});
canvas.addEventListener('pointerdown',e=>{if(e.pointerType!=='touch')return;mapCamera.pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(mapCamera.pointers.size===2){const [a,b]=[...mapCamera.pointers.values()];mapCamera.pinchDistance=Math.hypot(a.x-b.x,a.y-b.y);clickTarget=null}});
canvas.addEventListener('pointermove',e=>{if(!mapCamera.pointers.has(e.pointerId))return;mapCamera.pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(mapCamera.pointers.size===2){e.preventDefault();const[a,b]=[...mapCamera.pointers.values()],distance=Math.hypot(a.x-b.x,a.y-b.y);if(mapCamera.pinchDistance)setMapZoom(mapCamera.target*distance/mapCamera.pinchDistance);mapCamera.pinchDistance=distance;mapCamera.lastPinch=performance.now()}},{passive:false});
for(const event of['pointerup','pointercancel','pointerleave'])canvas.addEventListener(event,e=>{mapCamera.pointers.delete(e.pointerId);if(mapCamera.pointers.size<2)mapCamera.pinchDistance=0});
canvas.addEventListener('click',e=>{if(performance.now()-mapCamera.lastPinch<400){e.preventDefault();e.stopImmediatePropagation()}},true);
